import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    x_values = list(map(int, data[1:]))

    results = []

    for x in x_values:
        if x % 2 == 0:
            results.append("YES")
        else:
            results.append("NO")

    print("\n".join(results))

if __name__ == "__main__":
    main()
